UPDATE t_alert_data_contract SET schema_version='device-fingerprint-v1',source_system='t_feedback_identity',freshness_seconds=300,completeness_threshold=.990000
WHERE contract_code='device_fingerprint' AND contract_status='DRAFT';
UPDATE t_alert_data_contract SET schema_version='sdk-ingest-lifecycle-v1',source_system='t_sdk_ingest',freshness_seconds=60,completeness_threshold=.990000
WHERE contract_code IN ('urgency','processing_status','received_at','ingest_status','manual_takeover') AND contract_status='DRAFT';

