SELECT 'DEVICE_PERSISTENT_FAILURE','设备持续故障','USER_REQUEST','客服+产品研发',260,'shadow-v1','SHADOW','P1',JSON_OBJECT('combinator','ALL','conditions',JSON_ARRAY(JSON_OBJECT('metric','DEVICE_PERSISTENT_FAILURE_CANDIDATE_COUNT','operator','>=','threshold',1,'window','24h'))),JSON_OBJECT('threshold',0),JSON_OBJECT('channels',JSON_ARRAY('IN_APP'),'deliveryMode','TEST_ISOLATED'),60,0 WHERE NOT EXISTS(SELECT 1 FROM t_alert_rule WHERE rule_code='DEVICE_PERSISTENT_FAILURE' AND version_status='SHADOW');
